  if ((__shfl_sync(0xffffffffu, threadIdx.x / 32u, 0) == 0u)) {
    asm volatile("tcgen05.dealloc.cta_group::1.sync.aligned.b32 %0, %1;" :  : "r"(v2), "r"(512u) : "memory");
  }
}

// Launches attention_a3b_causal on `stream`, encoding its tensor maps as its parameter types require.
extern "C" cudaError_t attention_a3b_causal_launch(const __nv_bfloat16* Q, const __nv_bfloat16* K, const __nv_bfloat16* V, __nv_bfloat16* O, float* LSE, unsigned BH, unsigned seq, float scale_log2, unsigned rows, unsigned dim, cudaStream_t stream) {
