  CUtensorMap K_map;
  {
    const cuuint64_t dims[2] = {dim, rows};
    const cuuint64_t strides[1] = {static_cast<cuuint64_t>(dim) * 2u};
    const cuuint32_t box[2] = {64u, 128u};
    const cuuint32_t steps[2] = {1u, 1u};
    if (cuTensorMapEncodeTiled(&K_map, CU_TENSOR_MAP_DATA_TYPE_BFLOAT16, 2, const_cast<void*>(static_cast<const void*>(K)), dims, strides, box, steps,
        CU_TENSOR_MAP_INTERLEAVE_NONE, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B,
        CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) {
