  }
  void* args[] = {&Q_map, &K_map, &V_map, &O, &LSE, &BH, &seq, &scale_log2};
  return cudaLaunchKernel(reinterpret_cast<const void*>(attention_a3b_causal), dim3(((seq + 255u) / 256u), BH), dim3(512u), args, 201760u, stream);
